def summarize_ranges(nums: list[int]) -> str:
    # Remove duplicates and sort the numbers
    uniq = sorted(set(nums))
    if not uniq:
        return ""

    parts = []
    i = 0
    n = len(uniq)

    while i < n:
        start = uniq[i]
        # Extend the run while numbers are consecutive
        j = i + 1
        while j < n and uniq[j] == uniq[j - 1] + 1:
            j += 1

        run_len = j - i
        if run_len >= 3:
            # Collapse a long run into a..b format
            parts.append(f"{start}..{uniq[j - 1]}")
        else:
            # List each number individually for short runs
            for num in range(start, uniq[j - 1] + 1):
                parts.append(str(num))

        i = j

    return ",".join(parts)
